  <script>
    const monthName = document.getElementById("month-name");
    const calendarGrid = document.getElementById("calendar-grid");
    const summary = document.getElementById("summary");
    const toast = document.getElementById("toast");
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    let viewDate = new Date(today.getFullYear(), today.getMonth(), 1);
    let selectedDate = new Date(today);
    let selectedTime = "10:00 ص";

    const arabicMonths = [
      "يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
      "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"
    ];

    const arabicWeekdays = ["الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت"];

    function sameDay(first, second) {
      return first.getFullYear() === second.getFullYear() &&
        first.getMonth() === second.getMonth() &&
        first.getDate() === second.getDate();
    }

    function formatSelectedDate(date) {
      if (sameDay(date, today)) return "اليوم";
      return arabicWeekdays[date.getDay()];
    }

    function updateSummary() {
      const day = formatSelectedDate(selectedDate);
      const dateText = `${day}، ${selectedDate.getDate()} ${arabicMonths[selectedDate.getMonth()]}`;
      summary.textContent = `الموعد المختار: ${dateText}، ${selectedTime}`;
    }

    function renderCalendar() {
      monthName.textContent = `${arabicMonths[viewDate.getMonth()]} ${viewDate.getFullYear()}`;
      calendarGrid.innerHTML = "";

      const year = viewDate.getFullYear();
      const month = viewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const numberOfDays = new Date(year, month + 1, 0).getDate();

      // Saturday is index 6 in JavaScript; it is shown first in the Arabic calendar.
      const leadingEmptyDays = (firstDay.getDay() + 1) % 7;

      for (let index = 0; index < leadingEmptyDays; index++) {
        const empty = document.createElement("div");
        empty.className = "calendar-day empty";
        empty.setAttribute("role", "gridcell");
        calendarGrid.appendChild(empty);
      }

      for (let day = 1; day <= numberOfDays; day++) {
        const date = new Date(year, month, day);
        const button = document.createElement("button");
        button.type = "button";
        button.className = "calendar-day";
        button.textContent = day;
        button.setAttribute("role", "gridcell");
        button.setAttribute("aria-label", `${arabicWeekdays[date.getDay()]} ${day} ${arabicMonths[month]} ${year}`);

        const isPast = date < today;
        const isSunday = date.getDay() === 0;
        const isFriday = date.getDay() === 6;

        if (isPast) {
          button.classList.add("disabled");
          button.disabled = true;
        } else if (!isSunday && !isFriday) {
          button.classList.add("available");
        }

        if (sameDay(date, today)) button.classList.add("today");
        if (sameDay(date, selectedDate)) {
          button.classList.add("selected");
          button.setAttribute("aria-current", "date");
        }

        button.addEventListener("click", () => {
          selectedDate = new Date(date);
          renderCalendar();
          updateSummary();
        });

        calendarGrid.appendChild(button);
      }
    }

    document.getElementById("next-month").addEventListener("click", () => {
      viewDate = new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1);
      renderCalendar();
    });

    document.getElementById("prev-month").addEventListener("click", () => {
      const newMonth = new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1);
      if (newMonth >= new Date(today.getFullYear(), today.getMonth(), 1)) {
        viewDate = newMonth;
        renderCalendar();
      }
    });

    document.querySelectorAll(".time-slot").forEach(slot => {
      slot.addEventListener("click", () => {
